<?php
require_once __DIR__ . '/../config/bootstrap.php';
$period=current_period($pdo); $periodId=(int)($period['id']??0);
function ranking(PDO $pdo, int $periodId, string $category): array {
    $stmt=$pdo->prepare("SELECT k.*, (SELECT COUNT(*) FROM voting v WHERE v.kontestan_id=k.id AND v.periode_id=?) AS total_suara FROM kontestan k WHERE k.kategori=? ORDER BY total_suara DESC, k.nomor_peserta ASC");
    $stmt->execute([$periodId,$category]); return $stmt->fetchAll();
}
$kakang=ranking($pdo,$periodId,'Kakang'); $senduk=ranking($pdo,$periodId,'Senduk');
$totalK=array_sum(array_column($kakang,'total_suara')); $totalS=array_sum(array_column($senduk,'total_suara'));
$page_title='Klasemen Voting'; require __DIR__ . '/../includes/header.php';
?>
<header class="page-head"><div class="container"><span class="eyebrow">Perolehan suara sementara</span><h1 class="mt-2">Klasemen Voting</h1><p><?= e($period['nama_periode'] ?? 'Belum ada periode voting') ?> · Pembaruan berdasarkan data database.</p></div></header>
<section class="section-pad"><div class="container"><div class="row g-3 mb-5"><div class="col-md-4"><div class="stat-card"><div class="stat-label">Total suara Kakang</div><div class="stat-value"><?= number_format($totalK) ?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Total suara Senduk</div><div class="stat-value"><?= number_format($totalS) ?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Total seluruh suara</div><div class="stat-value"><?= number_format($totalK+$totalS) ?></div></div></div></div>
<div class="row g-5"><div class="col-lg-6"><h2 class="fw-bold mb-3">Kakang</h2><?php $arr=$kakang;$total=$totalK; if(!$arr): ?><div class="empty-state">Belum ada data kontestan.</div><?php else: ?><?php foreach($arr as $i=>$c): $pct=$total?round($c['total_suara']/$total*100,1):0; ?><div class="panel-card mb-3"><div class="d-flex gap-3 align-items-center"><img src="<?= $c['foto']?url('uploads/'.rawurlencode($c['foto'])):url('assets/img/placeholder.svg') ?>" style="width:65px;height:65px;object-fit:cover;border-radius:14px" alt=""><div class="flex-grow-1"><div class="d-flex justify-content-between gap-2"><div><span class="small-muted">#<?= $i+1 ?> · <?= e($c['nomor_peserta']) ?></span><h5 class="fw-bold mb-1"><?= e($c['nama']) ?></h5></div><strong><?= number_format($c['total_suara']) ?> suara</strong></div><div class="progress mt-2"><div class="progress-bar" style="width:<?= $pct ?>%"></div></div><div class="small-muted mt-1"><?= $pct ?>% dari suara kategori Kakang</div></div></div></div><?php endforeach; ?><?php endif; ?></div>
<div class="col-lg-6"><h2 class="fw-bold mb-3">Senduk</h2><?php $arr=$senduk;$total=$totalS; if(!$arr): ?><div class="empty-state">Belum ada data kontestan.</div><?php else: ?><?php foreach($arr as $i=>$c): $pct=$total?round($c['total_suara']/$total*100,1):0; ?><div class="panel-card mb-3"><div class="d-flex gap-3 align-items-center"><img src="<?= $c['foto']?url('uploads/'.rawurlencode($c['foto'])):url('assets/img/placeholder.svg') ?>" style="width:65px;height:65px;object-fit:cover;border-radius:14px" alt=""><div class="flex-grow-1"><div class="d-flex justify-content-between gap-2"><div><span class="small-muted">#<?= $i+1 ?> · <?= e($c['nomor_peserta']) ?></span><h5 class="fw-bold mb-1"><?= e($c['nama']) ?></h5></div><strong><?= number_format($c['total_suara']) ?> suara</strong></div><div class="progress mt-2"><div class="progress-bar" style="width:<?= $pct ?>%"></div></div><div class="small-muted mt-1"><?= $pct ?>% dari suara kategori Senduk</div></div></div></div><?php endforeach; ?><?php endif; ?></div></div><p class="small-muted mt-4">Terakhir dibuka: <?= date('d M Y H:i:s') ?> WIB. Klasemen dihitung langsung dari data voting tersimpan.</p></div></section>
